(6485716, 964026, 19825, '<td valign="top">Great shot. I love the eye and lighting on the nose. Everything works well including the crop and border.</td>', 'Great shot. I love the eye and lighting on the nose. Everything works well including the crop and border.', '2011-07-31 15:30:21.000000', NULL, 1),
(6485718, 963653, 19825, '<td valign="top">I love this one. Such depth in that eye.</td>', 'I love this one. Such depth in that eye.', '2011-07-31 15:30:50.000000', NULL, 1),
