(6487066, 963994, 113156, '<td valign="top">It took me a while to work it out but once i did i''m loving it.</td>', 'It took me a while to work it out but once i did i''m loving it.', '2011-08-01 14:33:22.000000', NULL, 1),
(6487093, 963907, 125275, '<td valign="top">This is a very cool shot. I like seeing the reflections in the eye, and the shadows on the iris are awesome. It''s an entire landscape.</td>', 'This is a very cool shot. I like seeing the reflections in the eye, and the shadows on the iris are awesome. It''s an entire landscape.', '2011-08-01 14:58:34.000000', NULL, 1),
(6487095, 964088, 125275, '<td valign="top">This is an awesome synesthetic approach. I love how the excitation of color seems to indicate pain. I really feel this meets the challenge very well, mainly because of the fact that I don''t need to read the title to understand what "sense" you are referring to.</td>', 'This is an awesome synesthetic approach. I love how the excitation of color seems to indicate pain. I really feel this meets the challenge very well, mainly because of the fact that I don''t need to read the title to understand what "sense" you are referring to.', '2011-08-01 15:00:15.000000', NULL, 1),
(6487097, 963950, 125275, '<td valign="top">Mmmm, that looks really thick and black. Is that even real coffee? Don''t tell me, I''d drink it anyway!</td>', 'Mmmm, that looks really thick and black. Is that even real coffee? Don''t tell me, I''d drink it anyway!', '2011-08-01 15:00:57.000000', NULL, 1),
(6487098, 964059, 125275, '<td valign="top">I like this regardless of the recent bug macro challenge. I hope nobody dings you for that, it would be unfair. :-D I love the clarity and DOF.</td>', 'I like this regardless of the recent bug macro challenge. I hope nobody dings you for that, it would be unfair. :-D I love the clarity and DOF.', '2011-08-01 15:01:59.000000', NULL, 1),
(6487100, 964017, 125275, '<td valign="top">This is a nice shot. Nice frozen action.</td>', 'This is a nice shot. Nice frozen action.', '2011-08-01 15:02:25.000000', NULL, 1),
(6487101, 963777, 125275, '<td valign="top">I like the glowing in this, to me it indicates a visualization of the pain he is feeling.</td>', 'I like the glowing in this, to me it indicates a visualization of the pain he is feeling.', '2011-08-01 15:03:10.000000', NULL, 1),
(6487102, 963270, 125275, '<td valign="top">Cool! This definitely portrays "sound" to me.</td>', 'Cool! This definitely portrays "sound" to me.', '2011-08-01 15:03:41.000000', NULL, 1),
(6487104, 964112, 125275, '<td valign="top">I like this image. The title helps with the intended message, but the image also speaks enough on its own. The purple goes well with the green. Nice processing for this image.</td>', 'I like this image. The title helps with the intended message, but the image also speaks enough on its own. The purple goes well with the green. Nice processing for this image.', '2011-08-01 15:04:33.000000', NULL, 1),
(6487106, 964060, 125275, '<td valign="top">I like this because it seems to portray a "softness" to it.</td>', 'I like this because it seems to portray a "softness" to it.', '2011-08-01 15:05:06.000000', NULL, 1),
(6487109, 963988, 125275, '<td valign="top">I think this is a well captured moment. Is this the set up for the "a touch to late" picture also in this challenge?</td>', 'I think this is a well captured moment. Is this the set up for the "a touch to late" picture also in this challenge?', '2011-08-01 15:05:56.000000', NULL, 1),
(6487118, 963387, 125275, '<td valign="top">This doesn''t portray (to me) the smell, but rather the striking visual beauty of a rose. It''s a very pretty shot.</td>', 'This doesn''t portray (to me) the smell, but rather the striking visual beauty of a rose. It''s a very pretty shot.', '2011-08-01 15:08:26.000000', NULL, 1),
