INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6491741, 963868, 127411, '<td valign="top">naughty but nice</td>', 'naughty but nice', '2011-08-03 17:27:44.000000', NULL, 0),
(6491763, 964010, 117717, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by mariuca:</b></div><hr/><i> Amazing nest! Never seen one like this, with a bad hair day! Just love it. Whereis it taken? </i></td></tr></table> <br/> <br/>This pair of ospreys built their nest on a crane at the Iroquois Locks last year which was not the safest of places for them,  fortunately some of the lock employees constructed a safe &amp; sturdy base and then hoisted the nest onto it.  A great solution for the beautiful ospreys. Luckily they returned to the nest again this year.  It has been amazing to be able to see the young ones grow.  I try to go &amp; observe them every weekend. Patience definitely pays off!  I''ve seen the female bring in various fish, the male fly by the nest with a huge catfish, only to land on a distant tower to enjoy  dinner by himself!  Last weekend it was raining &amp; I thought it would be fantastic to see the osprey in the rain.  This ended up being the most amazing visit to date.  The largest baby was trying to summon up the courage to leave the nest!  The mom was encouraging him by slowly flying around the nest (usually, when she''s not out fishing or gathering more sticks &amp; seaweed to add to the nest, she either sits in the nest or on a nearby post &amp; she swoops to and from the nest rather quickly).  The young osprey gave it a valiant effort, hopping &amp; flapping, but wasn''t quite ready for lift off!  <br/> <br/>This is the only image I was able to capture where food is visible in the mothers beak.  Can''t wait for the weekend!</td>', 'Originally posted by mariuca: Amazing nest! Never seen one like this, with a bad hair day! Just love it. Whereis it taken?   This pair of ospreys built their nest on a crane at the Iroquois Locks last year which was not the safest of places for them,  fortunately some of the lock employees constructed a safe & sturdy base and then hoisted the nest onto it.  A great solution for the beautiful ospreys. Luckily they returned to the nest again this year.  It has been amazing to be able to see the young ones grow.  I try to go & observe them every weekend. Patience definitely pays off!  I''ve seen the female bring in various fish, the male fly by the nest with a huge catfish, only to land on a distant tower to enjoy  dinner by himself!  Last weekend it was raining & I thought it would be fantastic to see the osprey in the rain.  This ended up being the most amazing visit to date.  The largest baby was trying to summon up the courage to leave the nest!  The mom was encouraging him by slowly flying around the nest (usually, when she''s not out fishing or gathering more sticks & seaweed to add to the nest, she either sits in the nest or on a nearby post & she swoops to and from the nest rather quickly).  The young osprey gave it a valiant effort, hopping & flapping, but wasn''t quite ready for lift off!   This is the only image I was able to capture where food is visible in the mothers beak.  Can''t wait for the weekend!', '2011-08-03 18:04:00.000000', NULL, 0),
